function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || !Array.isArray(grid[0]) || grid[0].length < 1) return 'grid needs at least one row and one column.';
  const m = grid.length, n = grid[0].length;
  if (m * n > 100000) return 'grid may hold at most 10^5 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row of grid must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v >= m * n)) return 'Each cell is an integer from 0 to m * n - 1.';
  }
  if (grid[m - 1][n - 1] !== 0) return 'The bottom-right cell must be 0.';
  return null;
}

