function minimumVisitedCells(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const push = (heap, item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = (heap) => {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let i = 0;
    while (true) {
      const left = 2 * i + 1;
      const right = left + 1;
      let smallest = i;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === i) break;
      [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
      i = smallest;
    }
  };
  const rowHeaps = Array.from({ length: m }, () => []);
  const colHeaps = Array.from({ length: n }, () => []);
  let dist = Infinity;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      const rowHeap = rowHeaps[i];
      const colHeap = colHeaps[j];
      while (rowHeap.length > 0 && rowHeap[0][1] + grid[i][rowHeap[0][1]] < j) pop(rowHeap);
      while (colHeap.length > 0 && colHeap[0][1] + grid[colHeap[0][1]][j] < i) pop(colHeap);
      dist = i === 0 && j === 0 ? 1 : Infinity;
      if (rowHeap.length > 0) dist = Math.min(dist, rowHeap[0][0] + 1);
      if (colHeap.length > 0) dist = Math.min(dist, colHeap[0][0] + 1);
      if (dist !== Infinity) {
        push(rowHeap, [dist, j]);
        push(colHeap, [dist, i]);
      }
    }
  }
  return dist === Infinity ? -1 : dist;
}

