function minimumVisitedCells(grid) {
  // Plain BFS that tries every allowed move from every cell.
  const m = grid.length, n = grid[0].length;
  const seen = grid.map(row => row.map(() => false));
  let frontier = [[0, 0]];
  seen[0][0] = true;
  for (let visited = 1; frontier.length > 0; visited++) {
    const following = [];
    for (const [r, c] of frontier) {
      if (r === m - 1 && c === n - 1) return visited;
      for (let k = c + 1; k <= Math.min(n - 1, c + grid[r][c]); k++) {
        if (!seen[r][k]) { seen[r][k] = true; following.push([r, k]); }
      }
      for (let k = r + 1; k <= Math.min(m - 1, r + grid[r][c]); k++) {
        if (!seen[k][c]) { seen[k][c] = true; following.push([k, c]); }
      }
    }
    frontier = following;
  }
  return -1;
}

