function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n;
  if (size === 'small') {
    m = pick(1, 5);
    n = pick(1, 5);
  } else {
    const shape = rand();
    if (shape < 0.5) { m = 100; n = 100; }
    else if (shape < 0.7) { m = pick(20, 100); n = pick(20, 100); }
    else if (shape < 0.85) { m = 1; n = 100; }
    else { m = 100; n = pick(1, 3); }
  }
  const cap = m * n - 1;
  const zero = rand() * (size === 'small' ? 0.4 : 0.08);
  const far = rand() * (size === 'small' ? 0.15 : 0.03);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => {
    const roll = rand();
    if (roll < zero) return 0;
    if (roll < zero + far) return pick(0, cap);
    return Math.min(cap, pick(1, 3));
  }));
  grid[m - 1][n - 1] = 0;
  return [grid];
}
